// ---------- Profile data now comes from the real Spring Boot backend ----------
var AVATARS = ['🦸', '🧙', '🧚', '🤖', '👽', '🥷', '🏴‍☠️', '🧑‍🚀', '👻', '🧞', '🦹', '🧛', '🧟', '🧝', '👺', '🐲'];
// superhero, wizard, fairy, robot, alien, ninja, pirate, astronaut, ghost, genie,
// supervillain, vampire, zombie, elf, oni mask, dragon

// 10 bold, kid-friendly cartoon character avatars, generated by DiceBear (open-source,
// MIT-licensed avatar library — not based on any show, comic or movie character). Each
// "seed" below always produces the exact same character, so picking one gives a
// consistent look every time. Style: "adventurer" — bright, friendly cartoon kids.
var AVATAR_SEEDS = ['Felix', 'Aneka', 'Milo', 'Zara', 'Leo', 'Nova', 'Kai', 'Luna', 'Max', 'Ivy'];

function avatarUrl(seed) {
  return 'https://api.dicebear.com/9.x/adventurer/svg?seed=' + encodeURIComponent(seed) + '&backgroundType=solid';
}
var ALL_AVATAR_VALUES = AVATAR_SEEDS;

function avatarMarkup(value) {
  if (AVATAR_SEEDS.indexOf(value) !== -1) {
    return '<img src="' + avatarUrl(value) + '" alt="" style="width:100%;height:100%;display:block;object-fit:cover;">';
  }
  return value || AVATARS[0];
}

   var API_BASE = 'https://learnquest-nofa.onrender.com';

// ---------- Session expires 5 minutes after this page was opened ----------
var SESSION_DURATION_MS = 5 * 60 * 1000; // 5 minutes
setTimeout(function () {
  sessionStorage.removeItem('lq_currentUser');
  var expiredOverlay = document.getElementById('sessionExpiredOverlay');
  expiredOverlay.hidden = false;
  document.getElementById('sessionExpiredBtn').addEventListener('click', function () {
    window.location.href = 'login.html?expired=1';
  });
}, SESSION_DURATION_MS);

function getCurrent() {
  var raw = sessionStorage.getItem('lq_currentUser');
  return raw ? JSON.parse(raw) : null;
}
function setCurrent(obj) {
  sessionStorage.setItem('lq_currentUser', JSON.stringify(obj));
}

var current = getCurrent();

// Not logged in (or the tab/session expired) -> send back to the login page.
if (!current) {
  window.location.href = 'login.html';
}

// "record" is the live profile: name, email, points, avatar — straight from the database.
var record = current || { name: 'Student', points: 0, avatar: AVATARS[0] };
var email = current ? current.email : null;

var greetingEl = document.getElementById('greeting');
var pointsEl = document.getElementById('pointsValue');
var avatarBtn = document.getElementById('avatarBtn');

function paintProfile() {
  var name = record.name || 'Student';
  greetingEl.textContent = (current && current.isNew ? 'Welcome, ' : 'Welcome back, ') + name + '!';
  pointsEl.textContent = record.points || 0;
  avatarBtn.innerHTML = avatarMarkup(record.avatar);
}
paintProfile();

// ---------- Profile dropdown ----------
var profileDropdown = document.getElementById('profileDropdown');
var settingsBtn = document.getElementById('settingsBtn');
var logoutBtn = document.getElementById('logoutBtn');

function closeDropdown() {
  profileDropdown.hidden = true;
  avatarBtn.setAttribute('aria-expanded', 'false');
}

avatarBtn.addEventListener('click', function (e) {
  e.stopPropagation();
  var isOpen = !profileDropdown.hidden;
  profileDropdown.hidden = isOpen;
  avatarBtn.setAttribute('aria-expanded', String(!isOpen));
});
document.addEventListener('click', function (e) {
  if (!profileDropdown.hidden && !profileDropdown.contains(e.target) && e.target !== avatarBtn) {
    closeDropdown();
  }
});

logoutBtn.addEventListener('click', function () {
  sessionStorage.removeItem('lq_currentUser');
  window.location.href = 'login.html';
});

// ---------- Settings modal ----------
var overlay = document.getElementById('settingsOverlay');
var nameInput = document.getElementById('settingName');
var passInput = document.getElementById('settingPassword');
var confirmInput = document.getElementById('settingConfirm');
var avatarGrid = document.getElementById('avatarGrid');
var settingsError = document.getElementById('settingsError');
var selectedAvatar = record.avatar || AVATARS[0];

ALL_AVATAR_VALUES.forEach(function (value) {
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'avatar-option';
  b.dataset.value = value;
  b.innerHTML = avatarMarkup(value);
  b.setAttribute('aria-label', 'Choose the ' + value + ' avatar');
  b.addEventListener('click', function () {
    selectedAvatar = value;
    avatarGrid.querySelectorAll('.avatar-option').forEach(function (o) { o.classList.remove('selected'); });
    b.classList.add('selected');
  });
  avatarGrid.appendChild(b);
});

function markSelectedAvatar() {
  avatarGrid.querySelectorAll('.avatar-option').forEach(function (o) {
    o.classList.toggle('selected', o.dataset.value === selectedAvatar);
  });
}

settingsBtn.addEventListener('click', function () {
  closeDropdown();
  nameInput.value = record.name || '';
  passInput.value = '';
  confirmInput.value = '';
  selectedAvatar = record.avatar || AVATARS[0];
  markSelectedAvatar();
  settingsError.hidden = true;
  overlay.hidden = false;
  nameInput.focus();
});

document.getElementById('settingsCancel').addEventListener('click', function () {
  overlay.hidden = true;
});
overlay.addEventListener('click', function (e) {
  if (e.target === overlay) overlay.hidden = true;
});

document.getElementById('settingsSave').addEventListener('click', function () {
  var newName = nameInput.value.trim();
  var newPass = passInput.value;
  var confirmPass = confirmInput.value;

  if (!newName) {
    settingsError.textContent = 'Please enter a name.';
    settingsError.hidden = false;
    return;
  }
  if (newPass || confirmPass) {
    if (newPass.length < 6) {
      settingsError.textContent = 'New password must be at least 6 characters.';
      settingsError.hidden = false;
      return;
    }
    if (newPass !== confirmPass) {
      settingsError.textContent = 'Passwords do not match.';
      settingsError.hidden = false;
      return;
    }
  }
  settingsError.hidden = true;

  var saveBtn = document.getElementById('settingsSave');
  saveBtn.disabled = true;
  saveBtn.textContent = 'Saving...';

  fetch(API_BASE + '/api/auth/update', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      email: email,
      name: newName,
      password: newPass || null,
      avatar: selectedAvatar
    })
  })
    .then(function (response) {
      if (!response.ok) throw new Error('Could not save changes.');
      return response.json();
    })
    .then(function (updatedUser) {
      record = updatedUser;
      current = updatedUser;
      setCurrent(updatedUser);
      paintProfile();
      overlay.hidden = true;
    })
    .catch(function () {
      settingsError.textContent = 'Something went wrong saving your changes. Please try again.';
      settingsError.hidden = false;
    })
    .finally(function () {
      saveBtn.disabled = false;
      saveBtn.textContent = 'Save changes';
    });
});

// ---------- Confetti burst (a little celebration when a topic is picked) ----------
var CONFETTI_COLORS = ['#ffd23f', '#f5a742', '#5bc97e', '#4a74f0', '#ea5a3c', '#7fdcea', '#f6a3bd'];

function burstConfetti(originX, originY) {
  for (var i = 0; i < 18; i++) {
    var piece = document.createElement('span');
    piece.className = 'confetti-piece';
    var angle = Math.random() * Math.PI * 2;
    var distance = 60 + Math.random() * 70;
    piece.style.setProperty('--dx', Math.cos(angle) * distance + 'px');
    piece.style.setProperty('--dy', Math.sin(angle) * distance + 'px');
    piece.style.left = originX + 'px';
    piece.style.top = originY + 'px';
    piece.style.background = CONFETTI_COLORS[Math.floor(Math.random() * CONFETTI_COLORS.length)];
    piece.style.animationDelay = (Math.random() * 0.1) + 's';
    document.body.appendChild(piece);
    piece.addEventListener('animationend', function () { this.remove(); });
  }
}

// ---------- Topic selection -> difficulty popup ----------
var cards = document.querySelectorAll('.topic-card');
var difficultyOverlay = document.getElementById('difficultyOverlay');
var difficultyTopic = document.getElementById('difficultyTopic');
var difficultyButtons = document.querySelectorAll('.difficulty-btn');
var difficultyCancel = document.getElementById('difficultyCancel');
var chosenTopic = null;

cards.forEach(function (card) {
  card.addEventListener('click', function () {
    cards.forEach(function (c) { c.classList.remove('selected'); });
    card.classList.add('selected');
    chosenTopic = card.dataset.topic;

    var rect = card.getBoundingClientRect();
    burstConfetti(rect.left + rect.width / 2, rect.top + rect.height / 2);

    difficultyTopic.textContent = chosenTopic;
    difficultyOverlay.hidden = false;
  });
});

difficultyCancel.addEventListener('click', function () {
  difficultyOverlay.hidden = true;
});
difficultyOverlay.addEventListener('click', function (e) {
  if (e.target === difficultyOverlay) difficultyOverlay.hidden = true;
});

difficultyButtons.forEach(function (btn) {
  btn.addEventListener('click', function () {
    var difficulty = btn.dataset.difficulty;
    difficultyOverlay.hidden = true;
    window.location.href = 'quiz.html?topic=' + encodeURIComponent(chosenTopic) + '&level=' + encodeURIComponent(difficulty);
  });
});
